// deepCopyMap creates a deep copy of a map[string]interface{} via JSON serialization.
// This ensures that the JavaScript script cannot mutate the original data structure.
func deepCopyMap(src map[string]interface{}) (map[string]interface{}, error) {
    data, err := json.Marshal(src)
    if err != nil {
        return nil, fmt.Errorf("json marshal error: %w", err)
    }
    var dst map[string]interface{}
    if err := json.Unmarshal(data, &dst); err != nil {
        return nil, fmt.Errorf("json unmarshal error: %w", err)
    }
    return dst, nil
}

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
//
// Security measures:
// 1. Each script is executed in a fresh Otto VM to avoid cross-item contamination.
// 2. Dangerous global functions (eval, Function) are removed from the VM to prevent arbitrary
//    code execution and privilege escalation.
// 3. The item is deep-copied before injection, so that the JavaScript script cannot modify the
//    original input data.
//
// Note: This implementation does not enforce a timeout. In a production setting, you should
//       wrap the VM execution in a mechanism with a timeout (e.g., a separate process) to
//       mitigate denial-of-service attacks via infinite loops.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
    var result []map[string]interface{}

    for _, item := range items {
        // Deep copy the item to prevent JavaScript from mutating the original map.
        copyItem, err := deepCopyMap(item)
        if err != nil {
            return nil, fmt.Errorf("failed to deep copy item: %w", err)
        }

        // Create a fresh VM for each item to ensure complete isolation.
        vm := otto.New()

        // Remove dangerous global objects to harden the sandbox.
        _, err = vm.Run(`
            eval = undefined;
            Function = undefined;
        `)
        if err != nil {
            return nil, fmt.Errorf("failed to sanitize VM globals: %w", err)
        }

        // Inject the deep copy as the global variable 'item'.
        err = vm.Set("item", copyItem)
        if err != nil {
            return nil, fmt.Errorf("failed to set item: %w", err)
        }

        // Run the user-provided condition script.
        value, err := vm.Run(conditionScript)
        if err != nil {
            return nil, fmt.Errorf("script execution error: %w", err)
        }

        // Convert result to boolean using JavaScript truthiness.
        boolResult, err := value.ToBoolean()
        if err != nil {
            return nil, fmt.Errorf("failed to convert result to boolean: %w", err)
        }

        if boolResult {
            result = append(result, item) // Append the original (unmodified) item to the result.
        }
    }

    return result, nil
}

