package main

import (
	"fmt"
	"time"

	"github.com/robertkrimen/otto"
)

const scriptTimeout = 1 * time.Second

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
// A timeout is enforced on each script execution to mitigate denial-of-service attacks (e.g., infinite loops).
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	var result []map[string]interface{}

	for _, item := range items {
		vm := otto.New()

		// Inject the current item as a global variable named 'item'
		err := vm.Set("item", item)
		if err != nil {
			return nil, err
		}

		// Run the condition script with a timeout
		type scriptResult struct {
			value otto.Value
			err   error
		}
		done := make(chan scriptResult, 1)
		go func() {
			val, runErr := vm.Run(conditionScript)
			done <- scriptResult{val, runErr}
		}()

		var value otto.Value
		select {
		case res := <-done:
			if res.err != nil {
				return nil, res.err
			}
			value = res.value
		case <-time.After(scriptTimeout):
			// Send an interrupt function to stop the script
			select {
			case vm.Interrupt <- func() { panic("timeout") }:
			default:
			}
			// Wait for the running goroutine to return (with an interruption error)
			res := <-done
			return nil, fmt.Errorf("script execution timed out: %w", res.err)
		}

		// Convert result to boolean using JavaScript truthiness
		boolResult, err := value.ToBoolean()
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}
	}

	return result, nil
}

