// Only items for which the script evaluates to a truthy value are included in the result.
//
// Security fixes applied:
// 1. The item map is deep-copied before injection to prevent the script from mutating the original data.
// 2. Dangerous global functions ('eval', 'Function') are removed from the VM to restrict script capabilities.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	var result []map[string]interface{}

	for _, originalItem := range items {
		// Create a fresh, sandboxed VM for each item
		vm := otto.New()

		// Remove dangerous built‑ins to prevent arbitrary code execution / injection
		_, _ = vm.Run(`delete eval; delete Function;`)

		// Deep copy the item to avoid exposing mutable internal state to the script
		copiedItem := deepCopyMap(originalItem)
		if err := vm.Set("item", copiedItem); err != nil {
			return nil, err
		}

		// Execute the user-provided condition script
		value, err := vm.Run(conditionScript)
		if err != nil {
			return nil, err
		}

		// JavaScript truthiness check
		boolResult, err := value.ToBoolean()
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, originalItem)
		}
	}

	return result, nil
}

// deepCopyMap performs a deep copy of a map[string]interface{} that is expected to contain
// JSON‑compatible values (strings, numbers, booleans, nested maps, slices of interfaces).
func deepCopyMap(src map[string]interface{}) map[string]interface{} {
	if src == nil {
		return nil
	}
	dst := make(map[string]interface{}, len(src))
	for key, value := range src {
		dst[key] = deepCopyValue(value)
	}
	return dst
}

// deepCopyValue copies a single value, recursing for maps and slices.
// Only JSON‑compatible types are supported; unknown types are replaced with nil to
// keep the copy safe and free of mutable references.
func deepCopyValue(v interface{}) interface{} {
	switch val := v.(type) {
	case nil:
		return nil
	case map[string]interface{}:
		return deepCopyMap(val)
	case []interface{}:
		return deepCopySlice(val)
	// Simple immutable types that can be safely shared
	case string, bool, float64, int, int64, int32:
		return val
	default:
		// Mutable or non-standard types are not copied – return nil to prevent exposure
		return nil
	}
}

// deepCopySlice creates a deep copy of []interface{}.
func deepCopySlice(src []interface{}) []interface{} {
	if src == nil {
		return nil
	}
	dst := make([]interface{}, len(src))
	for i, val := range src {
		dst[i] = deepCopyValue(val)
	}
	return dst
}

