package main

import (
    "time"
    "errors"

    "github.com/robertkrimen/otto"
)

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
//
// Security considerations:
// - A new VM is created per item to prevent state leakage between items.
// - A 5-second timeout is enforced via vm.Interrupt to prevent denial-of-service attacks from infinite loops.
// - The item is deep-copied before being injected into the JavaScript environment to prevent mutation of the original data.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
    var result []map[string]interface{}

    // Sanity check: reject excessively long scripts (optional, basic protection).
    if len(conditionScript) > 10000 {
        return nil, errors.New("condition script exceeds maximum allowed length")
    }

    for _, item := range items {
        // Create a fresh VM for each item to achieve full isolation.
        vm := otto.New()

        // Set an interrupt channel to enforce a timeout of 5 seconds.
        // This prevents infinite loops or long-running computations from hanging the server.
        interrupt := make(chan func(), 1)
        vm.Interrupt = interrupt
        go func() {
            time.Sleep(5 * time.Second)
            close(interrupt)
        }()

        // Deep copy the item to prevent the script from mutating the original data.
        safeItem := deepCopyMap(item)

        // Inject the current item as a global variable named 'item'
        err := vm.Set("item", safeItem)
        if err != nil {
            return nil, err
        }

        // Run the condition script within the safety constraints.
        value, err := vm.Run(conditionScript)
        if err != nil {
            // Check if the error was caused by an interrupt (timeout).
            // The otto VM returns a generic error with the message "interrupted" when the interrupt channel is closed.
            if err.Error() == "interrupted" {
                return nil, errors.New("script execution timed out")
            }
            return nil, err
        }

        // Convert result to boolean using JavaScript truthiness.
        boolResult, err := value.ToBoolean()
        if err != nil {
            return nil, err
        }

        if boolResult {
            result = append(result, item) // original item is appended, not the copied one
        }
    }

    return result, nil
}

// deepCopyMap performs a recursive deep copy of a map[string]interface{} to avoid shared references.
func deepCopyMap(original map[string]interface{}) map[string]interface{} {
    if original == nil {
        return nil
    }
    copyMap := make(map[string]interface{})
    for key, value := range original {
        copyMap[key] = deepCopyValue(value)
    }
    return copyMap
}

// deepCopyValue recursively copies interface{} values, handling maps, slices, and primitives.
func deepCopyValue(value interface{}) interface{} {
    switch val := value.(type) {
    case map[string]interface{}:
        return deepCopyMap(val)
    case []interface{}:
        arrCopy := make([]interface{}, len(val))
        for i, v := range val {
            arrCopy[i] = deepCopyValue(v)
        }
        return arrCopy
    default:
        // Primitives (string, int, float64, bool, nil) are immutable by nature and can be returned directly.
        return val
    }
}

