package main

import (
	"fmt"
	"github.com/robertkrimen/otto"
)

// FilterItems filters the given slice of maps based on a JavaScript condition script.
// For each item, the script is executed with the item injected as the global variable "item".
//
// Parameters:
//   - conditionScript: a JavaScript expression that evaluates to a boolean (or truthy/falsy) value.
//   - items: a slice of maps representing the data items to filter.
//
// Returns:
//   - a new slice containing only the items for which the condition evaluates to true,
//     or an error if the script cannot be executed.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	vm := otto.New()
	var filtered []map[string]interface{}

	for _, item := range items {
		// Inject the current item as the global "item" variable
		err := vm.Set("item", item)
		if err != nil {
			return nil, fmt.Errorf("failed to set item: %w", err)
		}

		// Execute the condition script
		value, err := vm.Run(conditionScript)
		if err != nil {
			return nil, fmt.Errorf("script execution error: %w", err)
		}

		// Convert the returned value to a boolean (handles truthy/falsy values)
		boolVal, err := value.ToBoolean()
		if err != nil {
			return nil, fmt.Errorf("conversion to boolean: %w", err)
		}

		// Keep items for which the result is truthy
		if boolVal {
			filtered = append(filtered, item)
		}
	}

	return filtered, nil
}

func main() {
	// Example usage
	items := []map[string]interface{}{
		{"id": 1, "active": true},
		{"id": 2, "active": false},
		{"id": 3, "active": true},
	}
	script := "item.active == true"

	filtered, err := FilterItems(script, items)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Printf("Filtered: %v\n", filtered)
}

