package main

import (
	"github.com/robertkrimen/otto"
)

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	// Precompile the condition script to avoid recompilation for every item.
	// A temporary VM is used only for compilation; the resulting script can be reused in any VM.
	script, err := otto.New().Compile("", conditionScript)
	if err != nil {
		return nil, err
	}

	// Initialize result as an empty slice (rather than nil) for consistent return value.
	result := make([]map[string]interface{}, 0)

	for _, item := range items {
		// Create a fresh VM for each item to ensure complete isolation between evaluations.
		vm := otto.New()

		// Inject the current item into the JavaScript environment as the global variable 'item'.
		if err := vm.Set("item", item); err != nil {
			return nil, err
		}

		// Run the precompiled script in the isolated VM.
		value, err := vm.Run(script)
		if err != nil {
			return nil, err
		}

		// Determine truthiness according to JavaScript rules.
		boolResult, err := value.ToBoolean()
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}
	}

	return result, nil
}

