package main

import (
	"errors"
	"time"

	"github.com/robertkrimen/otto"
)

// Limit the execution time per item to prevent denial-of-service attacks
// via infinite loops, recursion bombs, or other long-running scripts.
const executeTimeout = 100 * time.Millisecond

// FilterItems filters a slice of map[string]interface{} items using a JavaScript
// condition script. The script is evaluated once per item, with the current item
// exposed as the global variable 'item'. The script should evaluate to a truthy
// or falsy value; items for which the script is truthy are included in the result.
//
// A per-item execution timeout protects against malicious scripts that could
// otherwise block the caller indefinitely.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	if conditionScript == "" {
		return nil, errors.New("condition script must not be empty")
	}

	var result []map[string]interface{}

	for _, item := range items {
		vm := otto.New()

		// Set up an interrupt channel that allows us to abort a runaway script.
		vm.Interrupt = make(chan func(), 1)
		done := make(chan struct{})

		go func() {
			select {
			case <-time.After(executeTimeout):
				// Send a function that will panic, causing the VM to return an error.
				vm.Interrupt <- func() {
					panic("script execution timeout exceeded")
				}
			case <-done:
				// The script finished before the timeout; nothing to do.
			}
		}()

		// Inject the current item as a global variable named 'item'.
		err := vm.Set("item", item)
		if err != nil {
			close(done)
			return nil, err
		}

		// Run the condition script.
		value, err := vm.Run(conditionScript)
		close(done) // Signal the timeout goroutine that execution has finished.

		if err != nil {
			return nil, err
		}

		// Convert the result to a boolean using JavaScript truthiness.
		boolResult, err := value.ToBoolean()
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}
	}

	return result, nil
}

