// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
// The script is evaluated once per item, with the current item exposed as the global variable 'item'.
// The script should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
// Security: A timeout is enforced per item to prevent Denial of Service via long-running scripts,
// and a stack depth limit mitigates stack overflow attacks.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	var result []map[string]interface{}

	// Set a reasonable timeout and stack limit to prevent resource abuse.
	const (
		scriptTimeout = 1 * time.Second
		maxStackDepth = 10000
	)

	for _, item := range items {
		vm := otto.New()
		vm.SetStackDepthLimit(maxStackDepth)

		// Inject the current item as a global variable named 'item'
		if err := vm.Set("item", item); err != nil {
			return nil, err
		}

		// Run the script with a timeout using the Interrupt channel.
		value, err := runWithTimeout(vm, conditionScript, scriptTimeout)
		if err != nil {
			return nil, fmt.Errorf("script execution error: %w", err)
		}

		boolResult, err := value.ToBoolean()
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item)
		}
	}

	return result, nil
}

// runWithTimeout executes the given script on the Otto VM, interrupting after the timeout.
func runWithTimeout(vm *otto.Otto, script string, timeout time.Duration) (otto.Value, error) {
	// Set up an interrupt channel. Closing it will abort VM execution.
	interrupt := make(chan func(), 1)
	vm.Interrupt = interrupt

	type result struct {
		val otto.Value
		err error
	}
	done := make(chan result, 1)

	go func() {
		val, err := vm.Run(script)
		done <- result{val, err}
	}()

	select {
	case res := <-done:
		return res.val, res.err
	case <-time.After(timeout):
		// Interrupt the VM: closing the channel halts the script.
		close(interrupt)
		// Wait for the goroutine to finish and capture the error.
		res := <-done
		if res.err == nil {
			res.err = fmt.Errorf("script timed out after %v", timeout)
		}
		return otto.UndefinedValue(), res.err
	}
}

