package main

import (
	"errors"
	"time"

	"github.com/robertkrimen/otto"
)

// errTimeout is returned when a script evaluation exceeds the allowed time.
var errTimeout = errors.New("script evaluation timed out")

// deepCopy performs a deep copy of an interface{} value, handling maps and slices recursively.
func deepCopy(src interface{}) interface{} {
	switch v := src.(type) {
	case map[string]interface{}:
		copyMap := make(map[string]interface{}, len(v))
		for key, val := range v {
			copyMap[key] = deepCopy(val)
		}
		return copyMap
	case []interface{}:
		copySlice := make([]interface{}, len(v))
		for i, val := range v {
			copySlice[i] = deepCopy(val)
		}
		return copySlice
	default:
		return v
	}
}

// FilterItems filters a slice of map[string]interface{} items using a JavaScript condition script.
//
// The script is executed once per item, with the current item exposed as the global variable 'item'.
// It should evaluate to a truthy or falsy value; items for which the script is truthy are included in the result.
//
// Security measures:
//   - Each item is deep-copied before injection to prevent the script from mutating the original data.
//   - A per-script timeout of 1 second guards against infinite loops or excessive resource consumption.
func FilterItems(conditionScript string, items []map[string]interface{}) ([]map[string]interface{}, error) {
	var result []map[string]interface{}

	for _, item := range items {
		vm := otto.New()

		// Deep copy the item to protect the original from mutation by the script.
		copiedItem, ok := deepCopy(item).(map[string]interface{})
		if !ok {
			return nil, errors.New("failed to deep copy item")
		}

		if err := vm.Set("item", copiedItem); err != nil {
			return nil, err
		}

		// Set up an interrupt channel with a timeout to prevent runaway scripts.
		interrupt := make(chan func(), 1)
		vm.Interrupt = interrupt
		done := make(chan struct{})
		var timedOut bool

		go func() {
			select {
			case <-time.After(1 * time.Second):
				interrupt <- func() {
					timedOut = true
				}
			case <-done:
			}
		}()

		value, err := vm.Run(conditionScript)
		close(done)

		if timedOut {
			return nil, errTimeout
		}

		if err != nil {
			return nil, err
		}

		boolResult, err := value.ToBoolean()
		if err != nil {
			return nil, err
		}

		if boolResult {
			result = append(result, item) // append the original, unmodified item
		}
	}

	return result, nil
}

